// Soal 2: Mengakses Elemen Array
const bahasaPemrograman = [
  "JavaScript",
  "PHP",
  "Python",
  "Java",
  "C#"
];

// 1. Bahasa pemrograman pertama (indeks 0)
console.log("1. Bahasa pertama:", bahasaPemrograman[0]);

// 2. Bahasa pemrograman ketiga (indeks 2)
console.log("2. Bahasa ketiga:", bahasaPemrograman[2]);

// 3. Bahasa pemrograman terakhir (menggunakan length - 1)
console.log("3. Bahasa terakhir:", bahasaPemrograman[bahasaPemrograman.length - 1]);

// 4. Akses elemen pada indeks 7
console.log("4. Akses indeks 7:", bahasaPemrograman[7]);
